Q: How To Make An Authenticated Request From Mongo Atlas Triggers To GCP PubSub A: <p>FYI, the marked answer here no longer works with the latest versions of <code>@google-cloud/pubsub</code> because of node dependencies that aren't supported. Me and Claude went at this for a while and landed on a solution that uses the REST API to publish events with no package dependencies, so I figured I'd share in case anyone else ends up here.</p>
<p>This solution still uses the service account JSON from GCP (which sucks, btw, and MongoDB should really be supporting Workload Identity Federation for functions by now), and makes use of the built in <code>utils.jwt.encode</code> to encode the JSON key and do a token exchange against <code>oauth2.googleapis.com/token</code> , then publishes the event with that new token.</p>
<p>Anyways, here's the code. It includes the token exchange and a retry w/ jitter, just FYI.</p>
<pre><code>/**
 * Relay function for the transactional outbox pattern.
 *
 * Uses the Pub/Sub REST API and context.http instead of the @google-cloud/pubsub
 * npm package, which is not compatible with the Atlas Functions runtime.
 *
 * Authentication flow:
 *   1. Read SA key from Atlas Secret via context.values.get()
 *   2. Build a JWT signed with utils.jwt.encode(&quot;RS256&quot;, ...)
 *   3. Exchange the JWT for an access token via Google's OAuth2 endpoint
 *   4. Call the Pub/Sub REST API with the access token
 *
 * CRITICAL: This function must NEVER throw an unhandled exception.
 * An unhandled throw suspends the trigger, which is an operational incident.
 */

// ---------------------------------------------------------------------------
// Environment Configuration
// ---------------------------------------------------------------------------
// These values change per Atlas project (dev, prod, etc.).
// Update them when deploying to a new environment.

/** Atlas Linked Data Source name (see App Services &gt; Linked Data Sources) */
const ATLAS_SERVICE_NAME = &quot;my-project-dev&quot;;

/** MongoDB database name */
const DATABASE_NAME = &quot;my_project_main&quot;;

/** Atlas Secret-Mapped-Value name containing the GCP service account key JSON */
const GCP_SECRET_NAME = &quot;gcpServiceAccountKey&quot;;

// ---------------------------------------------------------------------------

exports = async function relayOutboxEvent(changeEvent) {
  let doc;

  try {
    doc = changeEvent.fullDocument;

    if (!doc) {
      console.error(&quot;relayOutboxEvent: fullDocument is null — skipping&quot;);
      return;
    }

    const { _id, eventId, eventType, source, subject, topic, payload, status, createdAt } = doc;

    // Guard: skip if already processed (idempotency)
    if (status !== &quot;pending&quot;) {
      console.log(`relayOutboxEvent: skipping eventId=${eventId}, status=${status}`);
      return;
    }

    // Authenticate to GCP
    const saKey = JSON.parse(context.values.get(GCP_SECRET_NAME));
    const accessToken = await getAccessToken(saKey);

    // Build CloudEvents attributes for binary content mode
    const attributes = {
      &quot;ce-id&quot;: eventId,
      &quot;ce-type&quot;: eventType,
      &quot;ce-source&quot;: source,
      &quot;ce-subject&quot;: subject,
      &quot;ce-time&quot;: new Date(createdAt).toISOString(),
      &quot;ce-specversion&quot;: &quot;1.0&quot;,
      &quot;ce-datacontenttype&quot;: &quot;application/protobuf&quot;,
    };

    // Publish with retries
    const result = await publishWithRetry(saKey.project_id, accessToken, topic, payload, attributes);

    // Update outbox document status
    const collection = context.services
      .get(ATLAS_SERVICE_NAME)
      .db(DATABASE_NAME)
      .collection(&quot;outbox&quot;);

    if (result.success) {
      await collection.updateOne(
        { _id, status: &quot;pending&quot; },
        {
          $set: { status: &quot;published&quot;, publishedAt: new Date() },
          $inc: { attempts: result.attemptsMade },
        },
      );
      console.log(`relayOutboxEvent: published eventId=${eventId} messageId=${result.messageId}`);
    } else {
      const errorEntry = { timestamp: new Date(), message: result.error };
      const newStatus = &quot;failed&quot;;

      await collection.updateOne(
        { _id },
        {
          $set: { status: newStatus },
          $inc: { attempts: result.attemptsMade },
          $push: { errors: errorEntry },
        },
      );
      console.error(
        `relayOutboxEvent: ${result.permanent ? &quot;permanent failure&quot; : &quot;retries exhausted&quot;} eventId=${eventId} error=${result.error}`,
      );
    }
  } catch (outerErr) {
    // Top-level catch: log and attempt best-effort error recording. NEVER re-throw.
    console.error(`relayOutboxEvent FATAL: eventId=${doc?.eventId || &quot;unknown&quot;} error=${String(outerErr)}`);
    try {
      const collection = context.services
        .get(ATLAS_SERVICE_NAME)
        .db(DATABASE_NAME)
        .collection(&quot;outbox&quot;);

      if (doc?._id) {
        await collection.updateOne(
          { _id: doc._id },
          {
            $inc: { attempts: 1 },
            $push: { errors: { timestamp: new Date(), message: `Unhandled: ${String(outerErr)}` } },
          },
        );
      }
    } catch (innerErr) {
      console.error(`relayOutboxEvent: failed to record error: ${String(innerErr)}`);
    }
  }
};

// ---------------------------------------------------------------------------
// GCP Authentication — manual JWT grant
// ---------------------------------------------------------------------------

/**
 * Get a GCP access token using the JWT grant flow.
 * Builds a JWT with utils.jwt.encode(&quot;RS256&quot;, ...) and exchanges it
 * at Google's OAuth2 token endpoint.
 *
 * @param {object} saKey - Parsed GCP service account JSON key
 * @returns {string} OAuth2 access token
 */
async function getAccessToken(saKey) {
  const now = Math.floor(Date.now() / 1000);

  const header = { alg: &quot;RS256&quot;, typ: &quot;JWT&quot; };
  const claimSet = {
    iss: saKey.client_email,
    scope: &quot;https://www.googleapis.com/auth/pubsub&quot;,
    aud: &quot;https://oauth2.googleapis.com/token&quot;,
    iat: now,
    exp: now + 3600,
  };

  // Use Atlas's built-in JWT encoder which handles key parsing internally
  const jwt = utils.jwt.encode(&quot;RS256&quot;, claimSet, saKey.private_key, header);

  // Exchange JWT for access token
  const response = await context.http.post({
    url: &quot;https://oauth2.googleapis.com/token&quot;,
    headers: { &quot;Content-Type&quot;: [&quot;application/x-www-form-urlencoded&quot;] },
    body: `grant_type=urn%3Aietf%3Aparams%3Aoauth%3Agrant-type%3Ajwt-bearer&amp;assertion=${jwt}`,
    encodeBodyAsJSON: false,
  });

  const tokenBody = JSON.parse(response.body.text());

  if (!tokenBody.access_token) {
    throw new Error(`OAuth2 token exchange failed: ${JSON.stringify(tokenBody)}`);
  }

  return tokenBody.access_token;
}

// ---------------------------------------------------------------------------
// Pub/Sub REST API publishing with retry
// ---------------------------------------------------------------------------

/**
 * Publish a message to Pub/Sub via the REST API with exponential backoff retry.
 *
 * @param {string} projectId - GCP project ID
 * @param {string} accessToken - OAuth2 access token
 * @param {string} topicName - Target Pub/Sub topic name
 * @param {object} payload - BSON Binary payload from the outbox document
 * @param {object} attributes - CloudEvents attributes for binary content mode
 * @returns {{ success: boolean, attemptsMade: number, messageId?: string, permanent?: boolean, error?: string }}
 */
async function publishWithRetry(projectId, accessToken, topicName, payload, attributes) {
  const MAX_ATTEMPTS = 5; // Max ~7.5 seconds total with backoff
  const BASE_DELAY_MS = 500; // Initial delay for backoff, dramatically alters exponential curve, adjust with caution

  // payload is BSON Binary — convert to base64 for the REST API
  const payloadBase64 = typeof payload.toBase64 === &quot;function&quot; ? payload.toBase64() : BSON.Binary(payload).toBase64();

  const url = `https://pubsub.googleapis.com/v1/projects/${projectId}/topics/${topicName}:publish`;

  const body = JSON.stringify({
    messages: [
      {
        data: payloadBase64,
        attributes: attributes,
      },
    ],
  });

  let lastError = null;

  for (let attempt = 1; attempt &lt;= MAX_ATTEMPTS; attempt++) {
    try {
      const response = await context.http.post({
        url: url,
        headers: {
          Authorization: [`Bearer ${accessToken}`],
          &quot;Content-Type&quot;: [&quot;application/json&quot;],
        },
        body: body,
      });

      const statusCode = response.statusCode;

      if (statusCode &gt;= 200 &amp;&amp; statusCode &lt; 300) {
        const responseBody = JSON.parse(response.body.text());
        return { success: true, attemptsMade: attempt, messageId: responseBody.messageIds?.[0] };
      }

      const responseText = response.body.text();

      // Non-retryable: 4xx except 429
      if (statusCode &gt;= 400 &amp;&amp; statusCode &lt; 500 &amp;&amp; statusCode !== 429) {
        return { success: false, attemptsMade: attempt, permanent: true, error: `Pub/Sub ${statusCode}: ${responseText}` };
      }

      // Retryable: 429, 5xx
      lastError = `Pub/Sub ${statusCode}: ${responseText}`;
    } catch (err) {
      lastError = `Network error: ${err.message || String(err)}`;
    }

    // Exponential backoff with jitter before next attempt
    // jitter prevents thundering herd if multiple messages fail simultaneously
    if (attempt &lt; MAX_ATTEMPTS) {
      const delayMs = BASE_DELAY_MS * Math.pow(2, attempt - 1) + Math.floor(Math.random() * 200);
      await new Promise((resolve) =&gt; setTimeout(resolve, delayMs));
    }
  }

  return { success: false, attemptsMade: MAX_ATTEMPTS, permanent: false, error: lastError };
}
</code></pre>

